mapper.update:
update dy_audience_rank_batch
set room_id = #{roomId}, room_match_status = #{roomMatchStatus}
where batch_id = #{batchId}

update dy_audience_rank_batch
set is_current = 0
where room_scope_key = #{roomScopeKey}
  and comment_data_date = #{commentDataDate}
  and watch_data_date = #{watchDataDate}
  and batch_id != #{batchId}
  and is_current = 1

update dy_audience_followup
room_id = #{roomId}, owner_user_id = #{ownerUserId}, owner_name_snapshot = #{ownerNameSnapshot}, anchor_user_id = #{anchorUserId}, anchor_name_snapshot = #{anchorNameSnapshot}, controller_user_id = #{controllerUserId}, controller_name_snapshot = #{controllerNameSnapshot}, status_changed_at = if(not (status <=> #{status}), sysdate(), status_changed_at), status = #{status}, follow_result_code = #{followResultCode}, intent_level = #{intentLevel}, consult_model = #{consultModel}, order_no = #{orderNo}, priority = #{priority}, contact_phone = #{contactPhone}, contact_wechat = #{contactWechat}, reactivation_pending = #{reactivationPending}, qualification_reason = #{qualificationReason}, qualified_at = #{qualifiedAt}, last_contact_at = #{lastContactAt}, next_follow_at = #{nextFollowAt}, last_follow_result = #{lastFollowResult}, remark = #{remark}, close_reason = #{closeReason}, close_reason_code = #{closeReasonCode}, version = version + 1, update_by = #{updateBy}, update_time = sysdate()
where followup_id = #{followupId} and version = #{version}

mapper.select:
select 'NEW' stageCode, count(*) totalCount from dy_audience_followup f

    and f.status != 'OBSERVING'
    and f.room_id = #{roomId}
    and f.owner_user_id = #{ownerUserId}
    and f.first_seen_at >= #{beginDate}
    and f.first_seen_at < date_add(#{endDate}, interval 1 day)

union all
select 'CLAIMED', count(*) from dy_audience_followup f

    and f.owner_user_id is not null
    and f.room_id = #{roomId}
    and f.owner_user_id = #{ownerUserId}
    and f.first_seen_at >= #{beginDate}
    and f.first_seen_at < date_add(#{endDate}, interval 1 day)

union all
select 'CONTACTED', count(*) from dy_audience_followup f

    and f.status not in ('OBSERVING', 'UNASSIGNED', 'PENDING')
    and f.room_id = #{roomId}
    and f.owner_user_id = #{ownerUserId}
    and f.first_seen_at >= #{beginDate}
    and f.first_seen_at < date_add(#{endDate}, interval 1 day)

union all
select 'QUALIFIED', count(*) from dy_audience_followup f

    and (f.intent_level = 'HIGH' or f.status in ('QUALIFIED', 'QUOTED', 'ORDER_PENDING', 'ORDERED', 'CLOSED'))
    and f.room_id = #{roomId}
    and f.owner_user_id = #{ownerUserId}
    and f.first_seen_at >= #{beginDate}
    and f.first_seen_at < date_add(#{endDate}, interval 1 day)

union all
select 'ORDERED', count(*) from dy_audience_followup f

    and f.status in ('ORDERED', 'CLOSED') and f.order_no is not null and trim(f.order_no) != ''
    and f.room_id = #{roomId}
    and f.owner_user_id = #{ownerUserId}
    and f.first_seen_at >= #{beginDate}
    and f.first_seen_at < date_add(#{endDate}, interval 1 day)

select count(*) from dy_audience_followup
where owner_user_id = #{ownerUserId}
  and status not in ('ORDERED', 'CLOSED', 'INVALID')

